import {
  isLineCanvasEqual,
  lineAnimation,
} from '../functions/animations/line-canvas.js';
import { printLineBuilder } from '../functions/shapes/line-canvas.js';
import { useCanvas } from '../hooks/useCanvas.js';
import { useCanvasAnimation } from '../hooks/useCanvasAnimation.js';
import {
  FnCanvasAccessor,
  LineCanvasInstance,
  LineCanvasProps,
} from '../types/canvas-shape.js';

export function LineCanvas<Datum>(props: LineCanvasProps<Datum>) {
  const {
    radius,
    strokeWidth = 2,
    animation = { enabled: false },
    ...propsLineCanvas
  } = props;

  // Build how Line canvas should style
  const drawLine = printLineBuilder<Datum>(strokeWidth, radius);

  const drawLineCanvas = (
    ctx: CanvasRenderingContext2D,
    canvas: LineCanvasInstance<Datum>,
  ) => {
    drawLine(ctx, canvas, canvas.x, canvas.y);
  };

  // Define draw tick per animation lap for Lines shape
  const onTickAnimation = (
    progress: number,
    ctx: CanvasRenderingContext2D,
    lineCanvas: LineCanvasInstance<Datum>,
    prevCanvas?: LineCanvasInstance<Datum>,
  ) => {
    const lineTick = (x: FnCanvasAccessor<Datum>, y: FnCanvasAccessor<Datum>) =>
      drawLine(ctx, lineCanvas, x, y);
    lineAnimation(lineCanvas, progress, lineTick, prevCanvas);
  };

  // Register shape/draw
  const { draw } = useCanvasAnimation<LineCanvasInstance<Datum>, Datum>(
    propsLineCanvas,
    drawLineCanvas,
    animation.enabled ?? false,
    isLineCanvasEqual,
    onTickAnimation,
    animation.duration,
  );

  useCanvas('line', draw);

  return null;
}
